#define TG_ISLAND_COUNT_LO 5
#define TG_ISLAND_COUNT_SPAN 3
#define TG_ISLAND_TURN_LO TG_Q(-0.0955) /* -0.6 rad in turns */
#define TG_ISLAND_TURN_HI TG_Q(0.0955)
#define TG_ISLAND_HOP_LO_WU 1500
#define TG_ISLAND_HOP_HI_WU 2300
#define TG_ISLAND_PAD_WU 800
#define TG_ISLAND_R_LO TG_Q(0.02)
#define TG_ISLAND_R_HI TG_Q(0.037)
#define TG_ISLAND_PEAK_LO_WU 300
#define TG_ISLAND_PEAK_HI_WU 900
#define TG_ISLAND_SKIP_WU (-50)
#define TG_ISLAND_FOOT_WU (-200)
#define TG_MIN_RELIEF_WU 2500
#define TG_DRY_LEVEL_WU 60
#define TG_BENCH_STEP_WU 300
#define TG_BENCH_SHARE_LO TG_Q(0.15)
#define TG_BENCH_SHARE_HI TG_Q(0.65)
#define TG_BENCH_BLEND TG_Q(0.06)
#define TG_BENCH_FADE_LO_WU 150
#define TG_BENCH_FADE_HI_WU 450
#define TG_BENCH_TILT TG_Q(0.15)
#define TG_BENCH_RISE TG_Q(0.85)
#define TG_BENCH_RISE_LO TG_Q(0.7)
#define TG_SMOOTH_3 (3 * TG_ONE)
#define TG_SMOOTH_2 2
#define TG_CANYON_HALF_COVER TG_HALF

typedef struct { uint64_t seed; uint32_t k; } tg_rng;
typedef struct { uint32_t n, m; int64_t cv; int32_t *e; } tg_grid; /* n by m cells, cv = canvas side in Q16 wu */

static int32_t tg_draw(tg_rng *r) {
    int32_t v = om_tn_value2(r->seed, (int32_t)(r->k * (uint32_t)TG_ONE), 0);
    r->k++;
    return (v + TG_ONE) >> 1;
}
static int64_t tg_range(tg_rng *r, int64_t lo, int64_t hi) { return lo + (((hi - lo) * tg_draw(r)) >> TG_SHIFT); }
static int64_t tg_clamp(int64_t v, int64_t lo, int64_t hi) { return v < lo ? lo : (v > hi ? hi : v); }
static int64_t tg_lerp(int64_t a, int64_t b, int64_t t) { return a + (((b - a) * t) >> TG_SHIFT); }
static int64_t tg_smooth(int64_t t) {
    t = tg_clamp(t, 0, TG_ONE);
    return (((t * t) >> TG_SHIFT) * (TG_SMOOTH_3 - TG_SMOOTH_2 * t)) >> TG_SHIFT;
}
/* smoothstep(a, b, v) with a <= b in the same units */
static int64_t tg_step(int64_t a, int64_t b, int64_t v) {
    if (b <= a) return v >= b ? TG_ONE : 0;
    return tg_smooth(((v - a) << TG_SHIFT) / (b - a));
}
static uint64_t tg_isqrt(uint64_t v) {
    uint64_t r = 0, bit = (uint64_t)1 << TG_TOP_BIT;
    while (bit > v) bit >>= 2;
    while (bit) {
        if (v >= r + bit) { v -= r + bit; r = (r >> 1) + bit; } else r >>= 1;
        bit >>= 2;
    }
    return r;
}
static int64_t tg_dist(int64_t dx, int64_t dy) { return (int64_t)tg_isqrt((uint64_t)(dx * dx + dy * dy)); }
static int32_t tg_noise(const tg_grid *g, uint64_t seed, uint32_t gx, uint32_t gy, int freq_x10) {
    int64_t cv = g->cv; /* Q16 wu */
    int64_t xq = ((int64_t)gx * TG_CELL_Q16 * freq_x10) / (cv / TG_ONE) / TG_FREQ_DIV;
    int64_t yq = ((int64_t)gy * TG_CELL_Q16 * freq_x10) / (cv / TG_ONE) / TG_FREQ_DIV;
    return om_tn_value2(seed, (int32_t)xq, (int32_t)yq);
}
static uint32_t tg_cell_of(const tg_grid *g, int64_t pos, uint32_t cells) {
    (void)g;
    return (uint32_t)tg_clamp((pos + TG_CELL_Q16 / 2) / TG_CELL_Q16, 0, (int64_t)cells - 1);
}
static int32_t *tg_e_at(const tg_grid *g, int64_t px, int64_t py) {
    return &g->e[tg_cell_of(g, tg_clamp(py, 0, INT64_MAX), g->m) * g->n + tg_cell_of(g, tg_clamp(px, 0, INT64_MAX), g->n)];
}
/* inclusive cell box around (cx, cy) with radius r (Q16 wu) */
static void tg_box(const tg_grid *g, int64_t cx, int64_t cy, int64_t r, int64_t *x0, int64_t *x1, int64_t *y0, int64_t *y1) {
    *x0 = tg_clamp((cx - r) < 0 ? 0 : (cx - r) / TG_CELL_Q16, 0, (int64_t)g->n - 1);
    *x1 = tg_clamp((cx + r + TG_CELL_Q16 - 1) / TG_CELL_Q16, 0, (int64_t)g->n - 1);
    *y0 = tg_clamp((cy - r) < 0 ? 0 : (cy - r) / TG_CELL_Q16, 0, (int64_t)g->m - 1);
    *y1 = tg_clamp((cy + r + TG_CELL_Q16 - 1) / TG_CELL_Q16, 0, (int64_t)g->m - 1);
}
static int64_t tg_wu(int64_t wu) { return wu * TG_ONE; }
static int64_t tg_cm(int64_t wu) { return wu * TG_CM_PER_WU; }

static void tg_elevation(tg_grid *g, uint64_t seed) {
    uint32_t n = g->n, m = g->m, x, y;
    int32_t *raw = (int32_t *)malloc((size_t)n * m * sizeof(int32_t));
    int32_t min_raw = INT32_MAX, max_raw = INT32_MIN;
    tg_rng rp = { seed + TG_SALT_PEAK, 0 };
    int64_t peak = (tg_cm(TG_PEAK_WU) * tg_range(&rp, TG_PEAK_FRAC_LO, TG_PEAK_FRAC_HI)) >> TG_SHIFT;
    int64_t sea = -((tg_cm(TG_PEAK_WU) * TG_SEA_DEPTH_FRAC) >> TG_SHIFT);
    for (y = 0; y < m; y++) for (x = 0; x < n; x++) {
        int64_t c = tg_noise(g, seed + TG_SALT_CONT, x, y, TG_FREQ_CONT_X10);
        int64_t h = tg_noise(g, seed + TG_SALT_HILLS, x, y, TG_FREQ_HILLS_X10);
        int32_t v = (int32_t)((c * TG_W_CONT + h * TG_W_HILLS) >> TG_SHIFT);
        raw[y * n + x] = v;
        if (v < min_raw) min_raw = v;
        if (v > max_raw) max_raw = v;
    }
    for (y = 0; y < m; y++) for (x = 0; x < n; x++) {
        int64_t v = raw[y * n + x], h = 0, d;
        if (v >= 0 && max_raw > 0) {
            int64_t f = (v << TG_SHIFT) / max_raw, s = f;
            int i;
            for (i = 0; i < TG_HEIGHT_EXP_STEPS; i++) s = (int64_t)tg_isqrt((uint64_t)s << TG_SHIFT);
            h = (((f * s) >> TG_SHIFT) * peak) >> TG_SHIFT;
        } else if (v < 0 && min_raw < 0) {
            h = (((v << TG_SHIFT) / min_raw) * sea) >> TG_SHIFT;
        }
        d = (tg_noise(g, seed + TG_SALT_DETAIL, x, y, TG_FREQ_DETAIL_X10) * tg_cm(TG_DETAIL_WU)) >> TG_SHIFT;
        h += d;
        {
            int64_t wy = (int64_t)y * TG_CELL_Q16;
            int64_t t = tg_step((g->cv * TG_EDGE_START) >> TG_SHIFT, g->cv, wy);
            h -= (t * (((peak * TG_EDGE_PEAK_FRAC) >> TG_SHIFT) + tg_cm(TG_EDGE_FLAT_WU))) >> TG_SHIFT;
        }
        g->e[y * n + x] = (int32_t)h;
    }
    free(raw);
}

static int tg_mesa(tg_grid *g, uint64_t seed, tg_rng *r) {
    int64_t rad = (g->cv * tg_range(r, TG_MESA_R_LO, TG_MESA_R_HI)) >> TG_SHIFT;
    int64_t margin = (rad * TG_MESA_MARGIN) >> TG_SHIFT, cx = 0, cy = 0, base = 0, top, edge = tg_wu(TG_MESA_EDGE_WU);
    int64_t x0, x1, y0, y1, gx, gy;
    int found = 0, t;
    for (t = 0; t < TG_MESA_TRIES && !found; t++) {
        cx = tg_range(r, margin, g->cv - margin);
        cy = tg_range(r, margin, g->cv - margin);
        base = *tg_e_at(g, cx, cy);
        found = base > tg_cm(TG_MESA_BASE_LO_WU) && base < tg_cm(TG_MESA_BASE_HI_WU);
    }
    if (!found) return 0;
    top = base + tg_cm(TG_MESA_LIFT_WU);
    tg_box(g, cx, cy, ((rad * TG_MESA_BOX) >> TG_SHIFT) + edge, &x0, &x1, &y0, &y1);
    for (gy = y0; gy <= y1; gy++) for (gx = x0; gx <= x1; gx++) {
        int64_t px = gx * TG_CELL_Q16, py = gy * TG_CELL_Q16, d = tg_dist(px - cx, py - cy);
        int32_t wob = om_tn_value2(seed + TG_SALT_WOBBLE, (int32_t)(px / TG_MESA_WOBBLE_CELL_WU), (int32_t)(py / TG_MESA_WOBBLE_CELL_WU));
        int64_t rr = rad + ((rad * ((wob * TG_MESA_WOBBLE) >> TG_SHIFT)) >> TG_SHIFT);
        int64_t tt = tg_smooth(((rr + edge - d) << TG_SHIFT) / edge);
        int32_t *e = &g->e[gy * g->n + gx];
        *e = (int32_t)tg_lerp(*e, top, tt);
    }
    return 1;
}

static int tg_canyon(tg_grid *g, tg_rng *r) {
    int64_t half = tg_wu(TG_CANYON_HALF_WU), hs = half + tg_wu(TG_CANYON_SHOULDER_WU);
    int64_t depth = tg_cm(TG_CANYON_DEPTH_WU);
    size_t cells = (size_t)g->n * g->m, i;
    int32_t *carve = (int32_t *)malloc(cells * sizeof(int32_t));
    int cut = 0, a, ok;
    int64_t steps = ((g->cv / TG_ONE) * TG_CANYON_LEN_NUM / TG_CANYON_LEN_DEN) / TG_CANYON_STEP_WU, s;
    for (a = 0; a < TG_CANYON_TRIES; a++) {
        int64_t px = (g->cv * tg_range(r, TG_CANYON_START_LO, TG_CANYON_START_HI)) >> TG_SHIFT;
        int64_t py = (g->cv * tg_range(r, TG_CANYON_START_LO, TG_CANYON_START_HI)) >> TG_SHIFT;
        uint32_t heading, phase;
        if (*tg_e_at(g, px, py) < tg_cm(TG_CANYON_START_LO_WU)) continue;
        heading = (uint32_t)tg_range(r, 0, TG_ONE);
        phase = (uint32_t)tg_range(r, 0, TG_ONE);
        memset(carve, 0, cells * sizeof(int32_t));
        for (s = 0; s < steps; s++) {
            int64_t sway = (TG_CANYON_SWAY_TURN * (int64_t)om_tn_sin_q16((uint32_t)(s * TG_CANYON_SWAY_STEP + phase) & (TG_ONE - 1))) >> TG_SHIFT;
            uint32_t ang = (uint32_t)(heading + sway) & (TG_ONE - 1);
            int64_t x0, x1, y0, y1, gx, gy;
            px += (int64_t)om_tn_cos_q16(ang) * TG_CANYON_STEP_WU;
            py += (int64_t)om_tn_sin_q16(ang) * TG_CANYON_STEP_WU;
            tg_box(g, px, py, hs, &x0, &x1, &y0, &y1);
            for (gy = y0; gy <= y1; gy++) for (gx = x0; gx <= x1; gx++) {
                int64_t d = tg_dist(gx * TG_CELL_Q16 - px, gy * TG_CELL_Q16 - py);
                int32_t v;
                int32_t *c = &carve[gy * g->n + gx];
                if (d >= hs) v = 0; else if (d <= half) v = TG_ONE; else v = (int32_t)tg_smooth(((hs - d) << TG_SHIFT) / (hs - half));
                if (v > *c) *c = v;
            }
        }
        cut = 0;
        for (i = 0; i < cells; i++) if (carve[i] > TG_CANYON_HALF_COVER && g->e[i] > tg_cm(TG_CANYON_CUT_WU)) cut++;
        if (cut >= TG_CANYON_MIN_CUT) break;
    }
    ok = cut >= TG_CANYON_MIN_CUT;
    if (ok) for (i = 0; i < cells; i++) if (carve[i] > 0 && g->e[i] > tg_cm(TG_CANYON_FLOOR_WU)) {
        int64_t low = g->e[i] - depth;
        if (low < tg_cm(TG_CANYON_FLOOR_WU)) low = tg_cm(TG_CANYON_FLOOR_WU);
        g->e[i] = (int32_t)tg_lerp(g->e[i], low, carve[i]);
    }
    free(carve);
    return ok;
}

static int tg_islands(tg_grid *g, tg_rng *r) {
    int64_t px = 0, py = 0, heading, hop;
    int found = 0, t, placed = 0, count, k;
    for (t = 0; t < TG_ISLAND_TRIES && !found; t++) {
        px = (g->cv * tg_range(r, TG_CANYON_START_LO, TG_CANYON_START_HI)) >> TG_SHIFT;
        py = (g->cv * tg_range(r, TG_CANYON_START_LO, TG_CANYON_START_HI)) >> TG_SHIFT;
        found = *tg_e_at(g, px, py) < tg_cm(TG_ISLAND_SEA_WU);
    }
    if (!found) return 0;
    heading = tg_range(r, 0, TG_ONE);
    count = TG_ISLAND_COUNT_LO + (int)((tg_draw(r) * (int64_t)TG_ISLAND_COUNT_SPAN) >> TG_SHIFT);
    for (k = 0; k < count; k++) {
        int64_t rad, peak, x0, x1, y0, y1, gx, gy, pad = tg_wu(TG_ISLAND_PAD_WU);
        heading += tg_range(r, TG_ISLAND_TURN_LO, TG_ISLAND_TURN_HI);
        hop = tg_range(r, tg_wu(TG_ISLAND_HOP_LO_WU), tg_wu(TG_ISLAND_HOP_HI_WU));
        px += ((int64_t)om_tn_cos_q16((uint32_t)heading & (TG_ONE - 1)) * hop) >> TG_SHIFT;
        py += ((int64_t)om_tn_sin_q16((uint32_t)heading & (TG_ONE - 1)) * hop) >> TG_SHIFT;
        px = tg_clamp(px, pad, g->cv - pad);
        py = tg_clamp(py, pad, g->cv - pad);
        rad = (g->cv * tg_range(r, TG_ISLAND_R_LO, TG_ISLAND_R_HI)) >> TG_SHIFT;
        peak = tg_range(r, tg_cm(TG_ISLAND_PEAK_LO_WU), tg_cm(TG_ISLAND_PEAK_HI_WU));
        if (*tg_e_at(g, px, py) > tg_cm(TG_ISLAND_SKIP_WU)) continue;
        tg_box(g, px, py, rad, &x0, &x1, &y0, &y1);
        for (gy = y0; gy <= y1; gy++) for (gx = x0; gx <= x1; gx++) {
            int64_t d = tg_dist(gx * TG_CELL_Q16 - px, gy * TG_CELL_Q16 - py), s, cone;
            if (d >= rad) continue;
            s = ((rad - d) << TG_SHIFT) / rad; /* cone profile 1 - d/r to the 0.75; mockup 0.8 */
            s = (int64_t)tg_isqrt((uint64_t)s << TG_SHIFT);
            s = (s * (int64_t)tg_isqrt((uint64_t)s << TG_SHIFT)) >> TG_SHIFT;
            cone = tg_cm(TG_ISLAND_FOOT_WU) + (((peak - tg_cm(TG_ISLAND_FOOT_WU)) * s) >> TG_SHIFT);
            if (g->e[gy * g->n + gx] < cone) g->e[gy * g->n + gx] = (int32_t)cone;
        }
        placed++;
    }
    return placed > 0;
}

static void tg_relief(tg_grid *g) {
    size_t i, cells = (size_t)g->n * g->m;
    int64_t hi = INT32_MIN, need = tg_cm(TG_MIN_RELIEF_WU + TG_DRY_LEVEL_WU), k;
    for (i = 0; i < cells; i++) if (g->e[i] > hi) hi = g->e[i];
    if (hi >= need || hi <= 0) return;
    k = (need << TG_SHIFT) / hi;
    for (i = 0; i < cells; i++) if (g->e[i] > 0) g->e[i] = (int32_t)(((int64_t)g->e[i] * k) >> TG_SHIFT);
}

static void tg_bench(tg_grid *g, uint64_t seed) {
    size_t i, cells = (size_t)g->n * g->m, land = 0;
    tg_rng r = { seed + TG_SALT_BENCH_SHARE, 0 };
    int64_t share = tg_range(&r, TG_BENCH_SHARE_LO, TG_BENCH_SHARE_HI), thr, step = tg_cm(TG_BENCH_STEP_WU);
    int32_t *vals;
    uint32_t *hist;
    int64_t rank, seen = 0, b = 0;
    for (i = 0; i < cells; i++) if (g->e[i] > 0) land++;
    if (!land) return;
    vals = (int32_t *)malloc(cells * sizeof(int32_t));
    hist = (uint32_t *)calloc(TG_NOISE_BUCKETS, sizeof(uint32_t));
    for (i = 0; i < cells; i++) {
        vals[i] = g->e[i] > 0 ? tg_noise(g, seed + TG_SALT_BENCH, (uint32_t)(i % g->n), (uint32_t)(i / g->n), TG_FREQ_BENCH_X10) : 0;
        if (g->e[i] > 0) hist[vals[i] + TG_ONE]++;
    }
    rank = (share * (int64_t)(land - 1)) >> TG_SHIFT;
    while (b < TG_NOISE_BUCKETS && seen + (int64_t)hist[b] <= rank) seen += hist[b++];
    thr = b - TG_ONE;
    for (i = 0; i < cells; i++) {
        int64_t e = g->e[i], wgt, t, f, fr, terr;
        if (e <= 0) continue;
        wgt = tg_step(thr + TG_BENCH_BLEND, thr, vals[i]);
        wgt = (wgt * tg_step(tg_cm(TG_BENCH_FADE_LO_WU), tg_cm(TG_BENCH_FADE_HI_WU), e)) >> TG_SHIFT;
        t = (e << TG_SHIFT) / step;
        f = t & ~(int64_t)(TG_ONE - 1);
        fr = t - f;
        terr = (f + ((TG_BENCH_TILT * fr) >> TG_SHIFT) + ((TG_BENCH_RISE * tg_step(TG_BENCH_RISE_LO, TG_ONE, fr)) >> TG_SHIFT));
        terr = (terr * step) >> TG_SHIFT;
        g->e[i] = (int32_t)tg_lerp(e, terr, wgt);
    }
    free(vals);
    free(hist);
}

static void tg_peak_fit(tg_grid *g) {
    size_t i, cells = (size_t)g->n * g->m;
    int64_t hi = INT32_MIN, lo_cm = tg_cm(TG_PEAK_LO_WU), hi_cm = tg_cm(TG_PEAK_WU);
    for (i = 0; i < cells; i++) if (g->e[i] > hi) hi = g->e[i];
    if (hi > 0 && (hi < lo_cm || hi > hi_cm)) {
        int64_t k = ((hi < lo_cm ? lo_cm : hi_cm) << TG_SHIFT) / hi;
        for (i = 0; i < cells; i++) if (g->e[i] > 0) g->e[i] = (int32_t)(((int64_t)g->e[i] * k) >> TG_SHIFT);
    }
    for (i = 0; i < cells; i++) if (g->e[i] < 0) g->e[i] = 0;
}

static void tg_free(void *p) {
    om_terrain_state *st = (om_terrain_state *)p;
    if (!st) return;
    free(st->height_cm);
    free(st->band);
    free(st->walkable);
    free(st->slopes);
    for (int b = 0; b < OM_TERRAIN_BANDS; b++) free(st->walk[b]);
    free(st);
}

/* Bands the cells from the five floors: band k + 1 for the highest floor k whose range holds the cell, clamped, cells below
 * floor 0 in band 1 (the generator's rule). Shared by om_terrain_generate, ts_save_read and om_terrain_set_heights.
 * See also: the K-e5 paragraph of docs/architecture.md. */
static void ts_bands_from_floors(const int32_t *h, size_t n, const int32_t floors[OM_TERRAIN_BANDS], uint8_t *band) {
    int64_t lo = floors[0], step = (int64_t)floors[1] - lo;
    size_t i;
    if (step < 1) step = 1;
    for (i = 0; i < n; i++) {
        int64_t b = h[i] < lo ? 0 : (h[i] - lo) / step;
        band[i] = (uint8_t)(tg_clamp(b, 0, OM_TERRAIN_BANDS - 1) + 1);
    }
}

/* Process-wide on purpose: a per-state counter would give a freed and recreated world at the same address the same gen_id.
 * See also: gen_id in csrc/om_internal.h, the key in csrc/walk_route.c. */
static uint32_t ts_gen_counter;

int om_terrain_generate(om_world *w, uint64_t seed, double canvas_w, double canvas_h) {
    om_terrain_state *st;
    tg_grid g;
    tg_rng pick = { seed + TG_SALT_PICK, 0 };
    int64_t lo = INT64_MAX, hi = INT64_MIN, step;
    size_t i, cells;
    int first, li, dry;
    int32_t chosen[TG_LANDFORM_COUNT];
    if (!w) return -1;
    if (!(canvas_w > 0.0 && canvas_h > 0.0 && canvas_w <= TG_MAX_CANVAS_WU && canvas_h <= TG_MAX_CANVAS_WU)) return -1;
    if (om_map_set_canvas(w, canvas_w, canvas_h) != 0) return -1;
    g.n = (uint32_t)(canvas_w / OM_TERRAIN_CELL_WU);
    g.m = (uint32_t)(canvas_h / OM_TERRAIN_CELL_WU);
    if (g.n == 0 || g.m == 0) return -1;
    g.cv = tg_wu((int64_t)(canvas_w > canvas_h ? canvas_w : canvas_h));
    cells = (size_t)g.n * g.m;
    st = (om_terrain_state *)calloc(1, sizeof(*st));
    st->gen_id = ++ts_gen_counter;
    g.e = (int32_t *)malloc(cells * sizeof(int32_t));
    st->band = (uint8_t *)calloc(cells, 1);
    st->walkable = (uint8_t *)calloc(cells, 1);
    st->slopes = (om_slope *)calloc(OM_TERRAIN_SLOPE_CAP, sizeof(om_slope));
    tg_elevation(&g, seed);
    first = (int)((tg_draw(&pick) * (int64_t)TG_LANDFORM_COUNT) >> TG_SHIFT);
    if (first >= TG_LANDFORM_COUNT) first = TG_LANDFORM_COUNT - 1;
    for (li = 0; li < TG_LANDFORM_COUNT; li++) chosen[li] = li == first || tg_draw(&pick) < TG_LAND_PICK_FRAC;
    for (li = 0; li < TG_LANDFORM_COUNT; li++) {
        tg_rng r;
        if (!chosen[li]) continue;
        r.seed = seed + TG_SALT_MESA + (uint64_t)li;
        r.k = 0;
        if (li == 0) tg_mesa(&g, seed, &r);
        else if (li == 1) tg_canyon(&g, &r);
        else tg_islands(&g, &r);
    }
    tg_relief(&g);
    tg_bench(&g, seed);
    tg_peak_fit(&g);
    dry = 0;
    for (i = 0; i < cells; i++) if (g.e[i] > tg_cm(TG_DRY_LEVEL_WU)) {
        dry = 1;
        if (g.e[i] < lo) lo = g.e[i];
        if (g.e[i] > hi) hi = g.e[i];
    }
    if (!dry) {
        free(g.e);
        tg_free(st);
        return -1;
    }
    step = (hi - lo) / TG_BAND_DIV;
    if (step < 1) step = 1;
    for (i = 0; i < OM_TERRAIN_BANDS; i++) st->band_floor_cm[i] = (int32_t)(lo + step * (int64_t)i);
    ts_bands_from_floors(g.e, cells, st->band_floor_cm, st->band);
    st->present = 1;
    st->seed = seed;
    st->cells_w = g.n;
    st->cells_h = g.m;
    st->height_cm = g.e;
    if (w->terrain_state && w->terrain_state_free) w->terrain_state_free(w->terrain_state);
    w->terrain_state = st;
    w->terrain_state_free = tg_free;
    om_terrain_apply_ground(w);
    return 0;
}

/* ---- queries ---- */
#include <math.h>
void om_mapgen_cell_set_density(om_world *w, uint32_t layer, int32_t cx, int32_t cy, double density);
void om_move_terrain_changed(om_world *w);

#define TS_DIAG_Q16 46341 /* 0.70710678 in Q16: the mockup's diagonal reach */
#define TS_FOOT_CM 10000 /* footprint width, one cell, in cm */
#define TS_DEG_MAX 90
#define TS_TAN_COUNT 90
#define TS_TAN_INF ((int64_t)1 << 40) /* no limit: 90 degrees and up */
#define TS_DIRS 4
#define TS_RUN_MAX 64 /* provisional (2026-10-05): longest slope run, cells */
#define TS_SAMPLES_PER_CELL 2 /* walkable check every half cell along a slope */
#define TS_BLOCKED_DENSITY 1.0
#define TS_OPEN_DENSITY 0.0

/* constants-table: docs/bible/epics/E-01-layer-system.md R-200-03 (tan of 0 to 89 degrees in Q16, for OM_TP_TERRAIN_STEEP_DEG) */
static const int32_t ts_tan_q16[TS_TAN_COUNT] = {
    0, 1144, 2289, 3435, 4583, 5734, 6888, 8047, 9210, 10380, 11556, 12739, 13930, 15130, 16340, 17560, 18792, 20036,
    21294, 22566, 23853, 25157, 26478, 27818, 29179, 30560, 31964, 33392, 34846, 36327, 37837, 39378, 40951, 42560,
    44205, 45889, 47615, 49385, 51202, 53070, 54991, 56970, 59009, 61113, 63287, 65536, 67865, 70279, 72785, 75391,
    78103, 80930, 83882, 86969, 90203, 93595, 97161, 100917, 104880, 109070, 113512, 118230, 123255, 128622, 134369,
    140542, 147196, 154393, 162207, 170727, 180059, 190330, 201699, 214359, 228551, 244584, 262851, 283868, 308323,
    337153, 371673, 413778, 466313, 533748, 623533, 749080, 937208, 1250501, 1876705, 3754555
};
/* end constants-table */

static const om_terrain_state *ts_ro(const om_world *w) {
    const om_terrain_state *st = w ? (const om_terrain_state *)w->terrain_state : NULL;
    return st && st->present ? st : NULL;
}

static int64_t ts_floor_div(int64_t a, int64_t b) {
    int64_t q = a / b;
    return (a % b != 0 && (a < 0) != (b < 0)) ? q - 1 : q;
}

/* Height in cm at a Q16 wu position: bilinear between cell centres, clamped at the border. */
static int64_t ts_height_q(const om_terrain_state *st, int64_t xq, int64_t yq) {
    int64_t u = xq - TG_CELL_Q16 / 2, v = yq - TG_CELL_Q16 / 2;
    int64_t i = ts_floor_div(u, TG_CELL_Q16), j = ts_floor_div(v, TG_CELL_Q16);
    int64_t fx = ((u - i * TG_CELL_Q16) << TG_SHIFT) / TG_CELL_Q16, fy = ((v - j * TG_CELL_Q16) << TG_SHIFT) / TG_CELL_Q16;
    int64_t i0 = tg_clamp(i, 0, (int64_t)st->cells_w - 1), i1 = tg_clamp(i + 1, 0, (int64_t)st->cells_w - 1);
    int64_t j0 = tg_clamp(j, 0, (int64_t)st->cells_h - 1), j1 = tg_clamp(j + 1, 0, (int64_t)st->cells_h - 1);
    int64_t top = tg_lerp(st->height_cm[j0 * st->cells_w + i0], st->height_cm[j0 * st->cells_w + i1], fx);
    int64_t bot = tg_lerp(st->height_cm[j1 * st->cells_w + i0], st->height_cm[j1 * st->cells_w + i1], fx);
    return tg_lerp(top, bot, fy);
}

/* Steep limit as tan in Q16, by linear interpolation between whole degrees. */
static int64_t ts_limit_tan_q(const om_world *w) {
    double deg = om_tactical_get_param(w, OM_TP_TERRAIN_STEEP_DEG);
    int64_t i, frac;
    if (deg >= (double)TS_DEG_MAX) return TS_TAN_INF;
    if (deg < 0.0) deg = 0.0;
    i = (int64_t)deg;
    frac = (int64_t)((deg - (double)i) * (double)TG_ONE);
    if (i >= TS_TAN_COUNT - 1) return ts_tan_q16[TS_TAN_COUNT - 1];
    return ts_tan_q16[i] + (((int64_t)(ts_tan_q16[i + 1] - ts_tan_q16[i]) * frac) >> TG_SHIFT);
}

/* The mockup's footprint slope: four directions through the point, a cell wide; the steepest rise over the width. */
static int ts_walk_q(const om_terrain_state *st, int64_t tanq, int64_t xq, int64_t yq) {
    int64_t r = TG_CELL_Q16 / 2, rd = (r * TS_DIAG_Q16) >> TG_SHIFT, best = 0;
    int64_t ox[TS_DIRS] = { r, 0, rd, rd }, oy[TS_DIRS] = { 0, r, rd, -rd };
    int k;
    for (k = 0; k < TS_DIRS; k++) {
        int64_t d = ts_height_q(st, xq + ox[k], yq + oy[k]) - ts_height_q(st, xq - ox[k], yq - oy[k]);
        if (d < 0) d = -d;
        if (d > best) best = d;
    }
    return best * TG_ONE <= tanq * TS_FOOT_CM;
}

static int ts_in_cells(const om_terrain_state *st, int64_t cx, int64_t cy) {
    return cx >= 0 && cy >= 0 && cx < (int64_t)st->cells_w && cy < (int64_t)st->cells_h;
}

static int ts_cell_of(const om_terrain_state *st, double x, double y, int64_t *cx, int64_t *cy) {
    if (!(x >= 0.0 && y >= 0.0)) return 0;
    *cx = (int64_t)(x / OM_TERRAIN_CELL_WU);
    *cy = (int64_t)(y / OM_TERRAIN_CELL_WU);
    return ts_in_cells(st, *cx, *cy);
}

static int64_t ts_centre_q(int64_t c) { return c * TG_CELL_Q16 + TG_CELL_Q16 / 2; }

/* A slope's cells: the bounding box of its two endpoint cells (its run, the slopes being axis-aligned). */
static int ts_slope_box(const om_slope *s, int64_t *lox, int64_t *loy, int64_t *hix, int64_t *hiy) {
    int64_t ax = (int64_t)(s->x0 / OM_TERRAIN_CELL_WU), ay = (int64_t)(s->y0 / OM_TERRAIN_CELL_WU);
    int64_t bx = (int64_t)(s->x1 / OM_TERRAIN_CELL_WU), by = (int64_t)(s->y1 / OM_TERRAIN_CELL_WU);
    *lox = ax < bx ? ax : bx; *hix = ax < bx ? bx : ax;
    *loy = ay < by ? ay : by; *hiy = ay < by ? by : ay;
    return 1;
}

/* Walk masks per engine layer: (band == layer + 1 AND walkable) OR (slope cell with a band of layer + 1 AND walkable).
 * Re-derived by ts_analyse on generate and on load; never saved. */
static void ts_derive_masks(om_terrain_state *st) {
    size_t n = (size_t)st->cells_w * st->cells_h, i;
    uint32_t b, k;
    for (b = 0; b < OM_TERRAIN_BANDS; b++) {
        if (!st->walk[b]) st->walk[b] = (uint8_t *)calloc(n, 1);
        if (!st->walk[b]) continue;
        for (i = 0; i < n; i++) st->walk[b][i] = (uint8_t)(st->walkable[i] && st->band[i] == b + 1);
    }
    for (k = 0; k < st->slope_count; k++) {
        const om_slope *s = &st->slopes[k];
        int64_t lox, loy, hix, hiy, cx, cy;
        ts_slope_box(s, &lox, &loy, &hix, &hiy);
        for (cy = loy; cy <= hiy; cy++) for (cx = lox; cx <= hix; cx++) {
            size_t idx;
            if (!ts_in_cells(st, cx, cy)) continue;
            idx = (size_t)cy * st->cells_w + cx;
            if (!st->walkable[idx]) continue;
            for (b = 0; b < OM_TERRAIN_BANDS; b++)
                if (st->walk[b] && (s->lower_band == (int32_t)b + 1 || s->upper_band == (int32_t)b + 1)) st->walk[b][idx] = 1;
        }
    }
}

/* Walkable per cell centre, then slopes: a maximal straight run of walkable cells that crosses one band boundary,
 * found in ascending cell order and capped at OM_TERRAIN_SLOPE_CAP. */
static void ts_analyse(const om_world *w, om_terrain_state *st) {
    static const int dx[TS_DIRS] = { 1, 0, -1, 0 }, dy[TS_DIRS] = { 0, 1, 0, -1 };
    int64_t tanq = ts_limit_tan_q(w), cx, cy, cells = (int64_t)st->cells_w * st->cells_h;
    uint8_t *used = (uint8_t *)calloc((size_t)cells, 1);
    st->slope_count = 0;
    for (cy = 0; cy < (int64_t)st->cells_h; cy++) for (cx = 0; cx < (int64_t)st->cells_w; cx++)
        st->walkable[cy * st->cells_w + cx] = (uint8_t)ts_walk_q(st, tanq, ts_centre_q(cx), ts_centre_q(cy));
    if (!used) return;
    for (cy = 0; cy < (int64_t)st->cells_h; cy++) for (cx = 0; cx < (int64_t)st->cells_w; cx++) {
        int64_t idx = cy * st->cells_w + cx;
        int d;
        if (!st->walkable[idx] || used[idx]) continue;
        for (d = 0; d < TS_DIRS; d++) {
            int64_t nx = cx + dx[d], ny = cy + dy[d], bx = cx, by = cy, tx = nx, ty = ny, k, n, len;
            int lo = st->band[idx];
            om_slope *s;
            int ok = 1;
            if (st->slope_count >= OM_TERRAIN_SLOPE_CAP) break;
            if (!ts_in_cells(st, nx, ny) || !st->walkable[ny * st->cells_w + nx] || st->band[ny * st->cells_w + nx] != lo + 1) continue;
            for (k = 0; k < TS_RUN_MAX; k++) {
                int64_t px = bx - dx[d], py = by - dy[d];
                if (!ts_in_cells(st, px, py) || !st->walkable[py * st->cells_w + px] || st->band[py * st->cells_w + px] != lo) break;
                bx = px;
                by = py;
            }
            for (k = 0; k < TS_RUN_MAX; k++) {
                int64_t px = tx + dx[d], py = ty + dy[d];
                if (!ts_in_cells(st, px, py) || !st->walkable[py * st->cells_w + px] || st->band[py * st->cells_w + px] != lo + 1) break;
                tx = px;
                ty = py;
            }
            len = (tx - bx) + (ty - by);
            if (len < 0) len = -len;
            n = len * TS_SAMPLES_PER_CELL;
            for (k = 0; k <= n && ok; k++)
                ok = ts_walk_q(st, tanq, ts_centre_q(bx) + (ts_centre_q(tx) - ts_centre_q(bx)) * k / n,
                               ts_centre_q(by) + (ts_centre_q(ty) - ts_centre_q(by)) * k / n);
            if (!ok) continue;
            s = &st->slopes[st->slope_count++];
            s->x0 = ((double)bx + 0.5) * OM_TERRAIN_CELL_WU;
            s->y0 = ((double)by + 0.5) * OM_TERRAIN_CELL_WU;
            s->x1 = ((double)tx + 0.5) * OM_TERRAIN_CELL_WU;
            s->y1 = ((double)ty + 0.5) * OM_TERRAIN_CELL_WU;
            s->mx = (((double)cx + (double)nx) * 0.5 + 0.5) * OM_TERRAIN_CELL_WU;
            s->my = (((double)cy + (double)ny) * 0.5 + 0.5) * OM_TERRAIN_CELL_WU;
            s->length = sqrt((s->x1 - s->x0) * (s->x1 - s->x0) + (s->y1 - s->y0) * (s->y1 - s->y0));
            s->lower_band = lo;
            s->upper_band = lo + 1;
            for (k = 0; k <= len; k++) {
                int64_t ux = bx + (tx > bx ? k : (tx < bx ? -k : 0)), uy = by + (ty > by ? k : (ty < by ? -k : 0));
                used[uy * st->cells_w + ux] = 1;
            }
            break;
        }
    }
    free(used);
    ts_derive_masks(st);
}

int om_terrain_present(const om_world *w) {
    return ts_ro(w) != NULL;
}

double om_terrain_height_at(const om_world *w, double x, double y) {
    const om_terrain_state *st = ts_ro(w);
    int64_t cx, cy;
    if (!st || !ts_cell_of(st, x, y, &cx, &cy)) return 0.0;
    return (double)ts_height_q(st, (int64_t)(x * (double)TG_ONE), (int64_t)(y * (double)TG_ONE)) / (double)TG_CM_PER_WU;
}

int om_terrain_band_at(const om_world *w, double x, double y) {
    const om_terrain_state *st = ts_ro(w);
    int64_t cx, cy;
    if (!st || !ts_cell_of(st, x, y, &cx, &cy)) return 0;
    return st->band[cy * st->cells_w + cx];
}

int om_terrain_walkable_at(const om_world *w, double x, double y) {
    const om_terrain_state *st = ts_ro(w);
    int64_t cx, cy;
    if (!st || !ts_cell_of(st, x, y, &cx, &cy)) return 0;
    return ts_walk_q(st, ts_limit_tan_q(w), (int64_t)(x * (double)TG_ONE), (int64_t)(y * (double)TG_ONE));
}

int om_terrain_nearest_walkable(const om_world *w, double x, double y, double *ox, double *oy) {
    const om_terrain_state *st = ts_ro(w);
    int64_t cx, cy, r, rmax, bx = 0, by = 0, bd = -1;
    if (!ox || !oy || x != x || y != y) return -1;
    if (!st) { *ox = x; *oy = y; return 0; }
    if (om_terrain_walkable_at(w, x, y)) { *ox = x; *oy = y; return 0; }
    cx = x <= 0.0 ? 0 : (int64_t)(x / OM_TERRAIN_CELL_WU);
    cy = y <= 0.0 ? 0 : (int64_t)(y / OM_TERRAIN_CELL_WU);
    if (cx >= (int64_t)st->cells_w) cx = (int64_t)st->cells_w - 1;
    if (cy >= (int64_t)st->cells_h) cy = (int64_t)st->cells_h - 1;
    rmax = (int64_t)(st->cells_w > st->cells_h ? st->cells_w : st->cells_h);
    for (r = 0; r <= rmax; r++) {
        int64_t gy, gx;
        if (bd >= 0 && r * r > bd) break;
        for (gy = cy - r; gy <= cy + r; gy++) {
            int64_t step = (gy == cy - r || gy == cy + r) ? 1 : 2 * r;
            if (gy < 0 || gy >= (int64_t)st->cells_h) continue;
            for (gx = cx - r; gx <= cx + r; gx += step) {
                int64_t d = (gx - cx) * (gx - cx) + (gy - cy) * (gy - cy);
                if (gx >= 0 && gx < (int64_t)st->cells_w && (bd < 0 || d <= bd)
                    && om_terrain_walkable_at(w, ((double)gx + 0.5) * OM_TERRAIN_CELL_WU, ((double)gy + 0.5) * OM_TERRAIN_CELL_WU)) {
                    if (bd < 0 || d < bd || gy * (int64_t)st->cells_w + gx < by * (int64_t)st->cells_w + bx) { bd = d; bx = gx; by = gy; }
                }
            }
        }
    }
    if (bd < 0) return -1;
    *ox = ((double)bx + 0.5) * OM_TERRAIN_CELL_WU;
    *oy = ((double)by + 0.5) * OM_TERRAIN_CELL_WU;
    return 0;
}

void om_terrain_clear(om_world *w) {
    if (!w || !w->terrain_state) return;
    if (w->terrain_state_free) w->terrain_state_free(w->terrain_state);
    w->terrain_state = NULL;
    w->terrain_state_free = NULL;
}

/* Layer numbering is the engine's: band k is layer k - 1. A slope cell (a cell of a slope's run) counts on both bands. */
int om_terrain_ground_at(const om_world *w, int layer, double x, double y) {
    const om_terrain_state *st = ts_ro(w);
    int64_t cx, cy;
    int band;
    uint32_t i;
    if (!st || layer < 0 || layer >= OM_TERRAIN_BANDS || !ts_cell_of(st, x, y, &cx, &cy)) return 0;
    band = st->band[cy * st->cells_w + cx];
    if (layer == band - 1) return 1;
    for (i = 0; i < st->slope_count; i++) {
        const om_slope *s = &st->slopes[i];
        int64_t ax = (int64_t)(s->x0 / OM_TERRAIN_CELL_WU), ay = (int64_t)(s->y0 / OM_TERRAIN_CELL_WU);
        int64_t bx = (int64_t)(s->x1 / OM_TERRAIN_CELL_WU), by = (int64_t)(s->y1 / OM_TERRAIN_CELL_WU);
        int64_t lox = ax < bx ? ax : bx, hix = ax < bx ? bx : ax, loy = ay < by ? ay : by, hiy = ay < by ? by : ay;
        if (cx < lox || cx > hix || cy < loy || cy > hiy) continue;
        if ((s->lower_band == layer + 1 && s->upper_band == band) || (s->lower_band == band && s->upper_band == layer + 1)) return 1;
    }
    return 0;
}

uint32_t om_terrain_band_heights(const om_world *w, double *out, uint32_t cap) {
    const om_terrain_state *st = ts_ro(w);
    uint32_t i;
    if (!st || !out) return 0;
    for (i = 0; i < OM_TERRAIN_BANDS && i < cap; i++) out[i] = (double)st->band_floor_cm[i] / (double)TG_CM_PER_WU;
    return i;
}

uint32_t om_terrain_slope_count(const om_world *w) {
    const om_terrain_state *st = ts_ro(w);
    return st ? st->slope_count : 0;
}

int om_terrain_slope_get(const om_world *w, uint32_t i, om_slope *out) {
    const om_terrain_state *st = ts_ro(w);
    if (!st || !out || i >= st->slope_count) return -1;
    *out = st->slopes[i];
    return 0;
}

uint32_t om_terrain_cells(const om_world *w, uint32_t *w_cells, uint32_t *h_cells) {
    const om_terrain_state *st = ts_ro(w);
    if (w_cells) *w_cells = st ? st->cells_w : 0;
    if (h_cells) *h_cells = st ? st->cells_h : 0;
    return st ? st->cells_w * st->cells_h : 0;
}

int om_terrain_cell_band(const om_world *w, uint32_t cx, uint32_t cy) {
    const om_terrain_state *st = ts_ro(w);
    if (!st || cx >= st->cells_w || cy >= st->cells_h) return 0;
    return st->band[(size_t)cy * st->cells_w + cx];
}

uint32_t om_terrain_dump_bands(const om_world *w, uint8_t *out, uint32_t cap) {
    const om_terrain_state *st = ts_ro(w);
    uint32_t n;
    if (!st || !out) return 0;
    n = st->cells_w * st->cells_h;
    if (n > cap) n = cap;
    memcpy(out, st->band, n);
    return n;
}

void om_terrain_state_free(void *state) {
    tg_free(state);
}

/* R-200-02: layers 1..k-1 blocked at every cell of band k, the rest open; written over every layer so a regenerate
 * leaves nothing stale. Also derives the walkable cells and slopes, which generate cannot see.
 * See also: the call at the end of om_terrain_generate. */
void om_terrain_apply_ground(om_world *w) {
    om_terrain_state *st = w ? (om_terrain_state *)w->terrain_state : NULL;
    uint32_t cx, cy, layer;
    if (!st || !st->present) return;
    ts_analyse(w, st);
    for (cy = 0; cy < st->cells_h; cy++) for (cx = 0; cx < st->cells_w; cx++) {
        int band = st->band[(size_t)cy * st->cells_w + cx];
        for (layer = 0; layer < OM_LAYER_COUNT; layer++)
            om_mapgen_cell_set_density(w, layer, (int32_t)cx, (int32_t)cy, (int)layer < band - 1 ? TS_BLOCKED_DENSITY : TS_OPEN_DENSITY);
    }
    om_move_terrain_changed(w);
}

/* K-e5 test hook (header: om_terrain_set_heights; reach_allowlist.toml): the generator's floor and band rules on given heights.
 * See also: the call chain at the end of om_terrain_generate. */
int om_terrain_set_heights(om_world *w, const int32_t *cm, uint32_t cells_w, uint32_t cells_h) {
    om_terrain_state *st = w ? (om_terrain_state *)w->terrain_state : NULL;
    int64_t lo = INT64_MAX, hi = INT64_MIN, step;
    int32_t floors[OM_TERRAIN_BANDS];
    size_t i, n;
    int dry = 0;
    if (!st || !st->present || !cm || cells_w != st->cells_w || cells_h != st->cells_h) return 0;
    n = (size_t)cells_w * cells_h;
    for (i = 0; i < n; i++) if (cm[i] > tg_cm(TG_DRY_LEVEL_WU)) {
        dry = 1;
        if (cm[i] < lo) lo = cm[i];
        if (cm[i] > hi) hi = cm[i];
    }
    if (!dry) for (i = 0; i < n; i++) {
        if (cm[i] < lo) lo = cm[i];
        if (cm[i] > hi) hi = cm[i];
    }
    step = (hi - lo) / TG_BAND_DIV;
    if (step < 1) step = 1;
    for (i = 0; i < OM_TERRAIN_BANDS; i++) floors[i] = (int32_t)(lo + step * (int64_t)i);
    memcpy(st->height_cm, cm, n * sizeof(int32_t));
    memcpy(st->band_floor_cm, floors, sizeof floors);
    ts_bands_from_floors(st->height_cm, n, st->band_floor_cm, st->band);
    om_terrain_apply_ground(w);
    om_density_rebuild_inputs(w);
    return 1;
}

/* ---- net hooks (terrain stage 1 spec 2026-10-05) ---- */
#define TS_NET_PRIME 1099511628211ULL
#define TS_NET_SEED 0x74657272616e6eULL
#define TS_NET_MIX_SHIFT 29

/* Section 8 is shared: mapgen (and support under it) installs first, its hash is kept here
 * (a function pointer, identical for every world) and chained. Terrain has its own save slot (OM_SAVE_SLOT_TERRAIN). */
static uint64_t (*ts_prev_hash)(const om_world *w);

static uint64_t ts_word(uint64_t h, uint64_t v) {
    h = (h ^ v) * TS_NET_PRIME;
    return h ^ (h >> TS_NET_MIX_SHIFT);
}

static uint64_t ts_section_hash(const om_world *w) {
    const om_terrain_state *st = ts_ro(w);
    uint64_t prev = ts_prev_hash ? ts_prev_hash(w) : 0, h;
    size_t i;
    if (!st) return prev;
    h = ts_word(TS_NET_SEED, prev);
    h = ts_word(h, st->seed);
    h = ts_word(h, st->cells_w);
    h = ts_word(h, st->cells_h);
    for (i = 0; i < OM_TERRAIN_BANDS; i++) h = ts_word(h, (uint64_t)(int64_t)st->band_floor_cm[i]);
    for (i = 0; i < (size_t)st->cells_w * st->cells_h; i++) h = ts_word(h, (uint64_t)(int64_t)st->height_cm[i]);
    return h;
}

/* Save slot blob (little-endian): seed u64, cells_w u32, cells_h u32, five band floors i32 cm, heights i32 cm.
 * Walkable, slopes and bands are re-derived on load. Format version stays 6 (ledger TD-TERRAIN-save-slot). */
#define TS_SAVE_U64 8 /* bytes of a u64 */
#define TS_SAVE_I32 4 /* bytes of a u32 or i32 */
#define TS_SAVE_BYTE_BITS 8
#define TS_SAVE_OFF_W TS_SAVE_U64
#define TS_SAVE_OFF_H (TS_SAVE_OFF_W + TS_SAVE_I32)
#define TS_SAVE_OFF_FLOORS (TS_SAVE_OFF_H + TS_SAVE_I32)
#define TS_SAVE_HEAD (TS_SAVE_OFF_FLOORS + TS_SAVE_I32 * OM_TERRAIN_BANDS)

static void ts_put(uint8_t *out, uint64_t v, int bytes) {
    int i;
    for (i = 0; i < bytes; i++) out[i] = (uint8_t)(v >> (TS_SAVE_BYTE_BITS * i));
}

static uint64_t ts_get(const uint8_t *in, int bytes) {
    uint64_t v = 0;
    int i;
    for (i = 0; i < bytes; i++) v |= (uint64_t)in[i] << (TS_SAVE_BYTE_BITS * i);
    return v;
}

static uint32_t ts_save_size(const om_world *w) {
    const om_terrain_state *st = ts_ro(w);
    return st ? (uint32_t)(TS_SAVE_HEAD + TS_SAVE_I32 * (size_t)st->cells_w * st->cells_h) : 0;
}

static void ts_save_write(const om_world *w, uint8_t *out) {
    const om_terrain_state *st = ts_ro(w);
    size_t i, n;
    if (!st) return;
    n = (size_t)st->cells_w * st->cells_h;
    ts_put(out, st->seed, TS_SAVE_U64);
    ts_put(out + TS_SAVE_OFF_W, st->cells_w, TS_SAVE_I32);
    ts_put(out + TS_SAVE_OFF_H, st->cells_h, TS_SAVE_I32);
    for (i = 0; i < OM_TERRAIN_BANDS; i++) ts_put(out + TS_SAVE_OFF_FLOORS + TS_SAVE_I32 * i, (uint32_t)st->band_floor_cm[i], TS_SAVE_I32);
    for (i = 0; i < n; i++) ts_put(out + TS_SAVE_HEAD + TS_SAVE_I32 * i, (uint32_t)st->height_cm[i], TS_SAVE_I32);
}

/* Atomic: parse into scratch, install at the end. Bands are re-derived as generate does (clamp((h - floor0) / step)). */
static int ts_save_read(om_world *w, const uint8_t *buf, uint32_t len) {
    om_terrain_state *st;
    uint32_t cw, ch;
    size_t i, n;
    if (len == 0) return 0;
    if (!w || !buf || len < TS_SAVE_HEAD) return -1;
    cw = (uint32_t)ts_get(buf + TS_SAVE_OFF_W, TS_SAVE_I32);
    ch = (uint32_t)ts_get(buf + TS_SAVE_OFF_H, TS_SAVE_I32);
    if (cw == 0 || ch == 0 || cw > OM_TERRAIN_MAX_CELLS || ch > OM_TERRAIN_MAX_CELLS) return -1;
    n = (size_t)cw * ch;
    if ((size_t)len != TS_SAVE_HEAD + TS_SAVE_I32 * n) return -1;
    st = (om_terrain_state *)calloc(1, sizeof(*st));
    if (!st) return -1;
    st->gen_id = ++ts_gen_counter;
    st->height_cm = (int32_t *)malloc(n * sizeof(int32_t));
    st->band = (uint8_t *)calloc(n, 1);
    st->walkable = (uint8_t *)calloc(n, 1);
    st->slopes = (om_slope *)calloc(OM_TERRAIN_SLOPE_CAP, sizeof(om_slope));
    if (!st->height_cm || !st->band || !st->walkable || !st->slopes) { tg_free(st); return -1; }
    st->seed = ts_get(buf, TS_SAVE_U64);
    st->cells_w = cw;
    st->cells_h = ch;
    for (i = 0; i < OM_TERRAIN_BANDS; i++) st->band_floor_cm[i] = (int32_t)(uint32_t)ts_get(buf + TS_SAVE_OFF_FLOORS + TS_SAVE_I32 * i, TS_SAVE_I32);
    for (i = 0; i < n; i++) st->height_cm[i] = (int32_t)(uint32_t)ts_get(buf + TS_SAVE_HEAD + TS_SAVE_I32 * i, TS_SAVE_I32);
    ts_bands_from_floors(st->height_cm, n, st->band_floor_cm, st->band);
    st->present = 1;
    ts_analyse(w, st);
    if (w->terrain_state && w->terrain_state_free) w->terrain_state_free(w->terrain_state);
    w->terrain_state = st;
    w->terrain_state_free = tg_free;
    return 0;
}

void om_terrain_install_net_hooks(om_world *w) {
    w->terrain_state_size = ts_save_size;
    w->terrain_state_write = ts_save_write;
    w->terrain_state_read = ts_save_read;
    uint64_t (*cur)(const om_world *) = w->net_section_hash[OM_NET_SECTION_COUNT - 1];
    if (cur != ts_section_hash) ts_prev_hash = cur;
    w->net_section_hash[OM_NET_SECTION_COUNT - 1] = ts_section_hash;
}

uint32_t om_terrain_walk_mask(const om_world *w, int layer, uint8_t *out, uint32_t cap) {
    const om_terrain_state *st = ts_ro(w);
    uint32_t n, i;
    if (!st || layer < 0 || layer >= OM_TERRAIN_BANDS) return 0;
    n = st->cells_w * st->cells_h;
    for (i = 0; out && i < n && i < cap; i++) out[i] = st->walk[layer] ? st->walk[layer][i] : 0;
    return n;
}

int om_terrain_slope_at(const om_world *w, double x, double y, om_slope *out) {
    const om_terrain_state *st = ts_ro(w);
    int64_t cx, cy;
    int band;
    uint32_t i;
    if (!st || !ts_cell_of(st, x, y, &cx, &cy)) return -1;
    band = st->band[cy * st->cells_w + cx];
    for (i = 0; i < st->slope_count; i++) {
        const om_slope *s = &st->slopes[i];
        int64_t lox, loy, hix, hiy;
        ts_slope_box(s, &lox, &loy, &hix, &hiy);
        if (cx < lox || cx > hix || cy < loy || cy > hiy) continue;
        if (s->lower_band != band && s->upper_band != band) continue;
        if (out) *out = *s;
        return (int)i;
    }
    return -1;
}

#define TS_SIGHT_STEP_WU 25
#define TS_SIGHT_SKIP_WU 50

/* Terrain height in cm at a wu point, 0 off the map (as om_terrain_height_at). */
static int64_t ts_height_cm(const om_terrain_state *st, double x, double y) {
    int64_t cx, cy;
    if (!ts_cell_of(st, x, y, &cx, &cy)) return 0;
    return ts_height_q(st, (int64_t)(x * (double)TG_ONE), (int64_t)(y * (double)TG_ONE));
}

static int64_t ts_eye_cm(const om_world *w, const om_terrain_state *st, int layer, double x, double y) {
    int64_t h = ts_height_cm(st, x, y), floor_cm;
    if (layer < 0) layer = 0;
    if (layer >= OM_TERRAIN_BANDS) layer = OM_TERRAIN_BANDS - 1;
    floor_cm = st->band_floor_cm[layer];
    if (floor_cm > h) h = floor_cm;
    return h + (int64_t)(om_tactical_get_param(w, OM_TP_SIGHT_EYE_HEIGHT) * (double)TG_CM_PER_WU);
}

int om_terrain_sight_blocks(const om_world *w, int layer0, double x0, double y0, int layer1, double x1, double y1) {
    const om_terrain_state *st = ts_ro(w);
    double dx = x1 - x0, dy = y1 - y0, d;
    int64_t e0, e1, s;
    if (!st) return 0;
    d = sqrt(dx * dx + dy * dy);
    e0 = ts_eye_cm(w, st, layer0, x0, y0);
    e1 = ts_eye_cm(w, st, layer1, x1, y1);
    for (s = TS_SIGHT_STEP_WU; (double)s < d; s += TS_SIGHT_STEP_WU) {
        double t = (double)s / d;
        int64_t line;
        if (s < TS_SIGHT_SKIP_WU || d - (double)s < (double)TS_SIGHT_SKIP_WU) continue;
        line = e0 + (int64_t)((double)(e1 - e0) * t);
        if (ts_height_cm(st, x0 + dx * t, y0 + dy * t) > line) return 1;
    }
    return 0;
}

uint32_t om_terrain_get_heights(const om_world *w, int32_t *out, uint32_t cap) {
    const om_terrain_state *st = ts_ro(w);
    uint32_t n, cx, cy;
    if (!st || !out) return 0;
    n = st->cells_w * st->cells_h;
    if (cap < n) return 0;
    for (cy = 0; cy < st->cells_h; cy++)
        for (cx = 0; cx < st->cells_w; cx++)
            out[(size_t)cy * st->cells_w + cx] = (int32_t)ts_height_q(st, ts_centre_q(cx), ts_centre_q(cy));
    return n;
}
